/// <summary>
///    Creates a new instance of the <c>BOMCalcJobItemTaskBatchManager</c> class.
/// </summary>
/// <param name="_batchHeader">
///    A <c>BatchHeader</c> that is used when you create the batch tasks.
/// </param>
/// <param name="_currentBatch">
///    A <c>Batch</c> record that is used when you create the batch tasks.
/// </param>
/// <returns>
///    A new instance of the <c>BOMCalcJobItemTaskBatchManager</c> class.
/// </returns>
public static AVABPJobsServiceTaskBatchManager newFromBatchParameters(
    BatchHeader _batchHeader,
    Batch       _currentBatch)
{
    AVABPJobsServiceTaskBatchManager  AVABPJobsServiceTaskBatchManager;

    if (!_batchHeader)
    {
        throw error(Error::wrongUseOfFunction(funcname()));
    }

    AVABPJobsServiceTaskBatchManager = AVABPJobsServiceTaskBatchManager::construct();
    AVABPJobsServiceTaskBatchManager.parmBatchHeader(_batchHeader);
    AVABPJobsServiceTaskBatchManager.parmCurrentBatch(_currentBatch);

    return AVABPJobsServiceTaskBatchManager;
}

/// <summary>
/// N.Freidenberger 12.09.2025
/// </summary>
/// <param name = "_avaBPJobsContract">_avaBPJobsContract</param>
public void createBatchTasks(AVABPJobsContract      _avaBPJobsContract)
{
    KCS_KBVBuildingProjectTable         buildingProjectTable;
    KCS_KBVBuildingProjectTable         oldBuildingProjectTable;
    int                                 kbvIdLength;
    int                                 minNumOfBV;
    int                                 numOfBPToProcess;
    int                                 numInThreath;
    int                                 startPeriod, endPeriod;
    int                                 oldBVNum;
    int                                 rest;
    boolean                             newPeriod = false;
    int                                 newStartPeriod;
    str                                 startPeriodStr, endPeriodStr;

    minNumOfBV = str2Int(KCS_KBVParameters::find().NDX_KBVBuildingProjectIDFrom);

    select maxOf(KCS_KBVBuildingProjectID) from   buildingProjectTable;

    select maxof(KCS_KBVBuildingProjectID) from oldBuildingProjectTable
        where oldBuildingProjectTable.KCS_KBVBuildingProjectID < '1000000';

    kbvIdLength = strLen(buildingProjectTable.KCS_KBVBuildingProjectID);

    oldBVNum = str2Int(oldBuildingProjectTable.KCS_KBVBuildingProjectID);
    numOfBPToProcess = ((minNumOfBV > oldBVNum) ? minNumOfBV : (oldBVNum - minNumOfBV)) + (str2Int(buildingProjectTable.KCS_KBVBuildingProjectID) - 1000000);

    numInThreath = roundDown(numOfBPToProcess / 4 , 0);



    int            maxNumOfBV = str2int(buildingProjectTable.KCS_KBVBuildingProjectID);
    int            interval1 = maxNumOfBV / 100 * 80;
    int            interval2 = maxNumOfBV / 100 * 86;
    int            interval3 = maxNumOfBV / 100 * 92;

    startPeriod = minNumOfBV;

    while (endPeriod < maxNumOfBV)
    {
        if(((startPeriod + numInThreath) < oldBVNum) || newPeriod)
        {
            endPeriod   = startPeriod + (rest == 0 ? numInThreath : rest);
            newStartPeriod = endPeriod + 1;
            rest = 0;
        }
        else
        {
            newPeriod = true;
            endPeriod = oldBVNum;
            rest      = (startPeriod + numInThreath) - oldBVNum; 
            newStartPeriod = 1000000;
        }

        startPeriodStr = int2Str(startPeriod);
        while (strLen(startPeriodStr) < strLen('1000000'))
        {
            startPeriodStr = '0' + startPeriodStr;
        }
        endPeriodStr = int2Str(endPeriod);
        while (strLen(endPeriodStr) < strLen('1000000'))
        {
            endPeriodStr = '0' + endPeriodStr;
        }
        AVABPJobsCalculationBatchTaskController         AVABPJobsCalculationBatchTaskController;
        AVABPJobsCalculationBatchTaskController   = AVABPJobsCalculationBatchTaskController::newFromParameters(_avaBPJobsContract,[startPeriodStr,endPeriodStr,(endPeriod > maxNumOfBV ? endPeriodStr : '0000000')]);
        batchHeader.addRuntimeTask(AVABPJobsCalculationBatchTaskController,this.parmCurrentBatch().RecId);
        startPeriod = newStartPeriod;
    }

 /*   AVABPJobsCalculationBatchTaskController         AVABPJobsCalculationBatchTaskController1, AVABPJobsCalculationBatchTaskController2, AVABPJobsCalculationBatchTaskController3, AVABPJobsCalculationBatchTaskController4;

    AVABPJobsCalculationBatchTaskController1  = AVABPJobsCalculationBatchTaskController::newFromParameters(_avaBPJobsContract,[strRFix('0',kbvIdLength,'0'),strRFix(int2Str(interval1),kbvIdLength,'0'),strRFix('0',kbvIdLength,'0')]);
    AVABPJobsCalculationBatchTaskController2  = AVABPJobsCalculationBatchTaskController::newFromParameters(_avaBPJobsContract,[strRFix(int2Str(interval1+1),kbvIdLength,'0'),strRFix(int2Str(interval2),kbvIdLength,'0'),strRFix('0',kbvIdLength,'0')]);
    AVABPJobsCalculationBatchTaskController3  = AVABPJobsCalculationBatchTaskController::newFromParameters(_avaBPJobsContract,[strRFix(int2Str(interval2+1),kbvIdLength,'0'),strRFix(int2Str(interval3),kbvIdLength,'0'),strRFix('0',kbvIdLength,'0')]);
    AVABPJobsCalculationBatchTaskController4  = AVABPJobsCalculationBatchTaskController::newFromParameters(_avaBPJobsContract,[strRFix(int2Str(interval3+1),kbvIdLength,'0'),strRFix('0',kbvIdLength,'0'),strRFix('0',kbvIdLength,'0')]);

    batchHeader.addRuntimeTask(AVABPJobsCalculationBatchTaskController1,this.parmCurrentBatch().RecId);
    batchHeader.addRuntimeTask(AVABPJobsCalculationBatchTaskController2,this.parmCurrentBatch().RecId);
    batchHeader.addRuntimeTask(AVABPJobsCalculationBatchTaskController3,this.parmCurrentBatch().RecId);
    batchHeader.addRuntimeTask(AVABPJobsCalculationBatchTaskController4,this.parmCurrentBatch().RecId);  */



    batchHeader.save();
}
